import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const f=JSON.parse('{"title":"PageHeader","description":"","frontmatter":{},"headers":[],"relativePath":"components/page-header.md","filePath":"components/page-header.md"}'),d={name:"components/page-header.md"};function i(n,e,h,s,l,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="pageheader" tabindex="-1">PageHeader <a class="header-anchor" href="#pageheader" aria-label="Permalink to &quot;PageHeader&quot;">​</a></h1><p>PageHeader is the head of a page: a trail of links, the title and a note.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it as the head of a <a href="./page">Page</a>. The only control it holds is a borderless icon button beside the title (to rename, or to open a menu). The head of a part of the page is a <a href="./section">Section</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The title (h1)</td></tr><tr><td><code>note</code></td><td></td><td>One sentence under the title</td></tr><tr><td><code>crumbs</code></td><td></td><td>The trail of links above the title (a snippet)</td></tr><tr><td><code>titleEnd</code></td><td></td><td>An icon button beside the title (a snippet)</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>PageHeader is text and has no height of its own: the trail (caption, muted) is gap-md above the title, and the note (caption) gap-xs below it. The title stays on one line and ends with an ellipsis when it does not fit; the full text shows on hover. The button of <code>titleEnd</code> takes width but no height: it overlaps the centre of the title&#39;s ink, so that the title&#39;s line is as tall with it as without it. The Page holds the distance to the content.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/page-header/" title="PageHeader" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/page-header/" target="_blank" rel="noopener">PageHeader</a></figcaption></figure>',10)])])}const u=t(d,[["render",i]]);export{f as __pageData,u as default};
